INSERT INTO products (id, category_id, tax_category, brand_id, url_handle, title, description, price, compare_at_price, cost_per_item, sku, barcode, track_stock, stock, low_stock_threshold, in_stock, weight, weight_unit, length, width, height, dimension_unit, is_tax_exempt, is_active, seo_title, seo_description, created_at, updated_at) VALUES
(1, 3, 'standard', 4, 'aether-pulse-pro', '{"en": "Aether Pulse Pro"}', '{"en": "<p>A flagship phone built around a bright 6.7-inch display and an all-day battery. The matte aluminium frame stays cool in the hand, and the camera stack is tuned for natural colour rather than oversharpened drama.</p><h3>Highlights</h3><ul><li>6.7-inch 120Hz OLED with always-on display</li><li>Triple camera with dedicated night sensor</li><li>All-day battery with 45W wired and 25W wireless charging</li></ul><h3>Details</h3><ul><li><strong>Display:</strong> 6.7in OLED, 120Hz</li><li><strong>Storage:</strong> 256GB</li><li><strong>Protection:</strong> IP68</li></ul>"}', 899.99, 999.99, 360.00, 'SKU-0001', NULL, TRUE, 48, 5, TRUE, 0.50, 'kg', 20.00, 15.00, 8.00, 'cm', FALSE, TRUE, '{"en": "Aether Pulse Pro"}', '{"en": "Aether Pulse Pro"}', '2026-03-01 10:00:00', '2026-03-01 10:00:00'),
(2, 3, 'standard', 4, 'aether-pulse-lite', '{"en": "Aether Pulse Lite"}', '{"en": "<p>A lighter, faster everyday phone. Same clean industrial design as the Pro, with a focused dual camera and a battery that comfortably lasts past bedtime.</p><h3>Highlights</h3><ul><li>6.1-inch smooth OLED</li><li>Dual camera with night mode</li><li>Side fingerprint and face unlock</li></ul><h3>Details</h3><ul><li><strong>Display:</strong> 6.1in OLED, 90Hz</li><li><strong>Storage:</strong> 128GB</li><li><strong>Weight:</strong> 168g</li></ul>"}', 499.99, NULL, 200.00, 'SKU-0002', NULL, TRUE, 72, 5, TRUE, 0.50, 'kg', 20.00, 15.00, 8.00, 'cm', FALSE, TRUE, '{"en": "Aether Pulse Lite"}', '{"en": "Aether Pulse Lite"}', '2026-03-01 10:00:00', '2026-03-01 10:00:00'),
(3, 3, 'standard', 4, 'aether-fold-air', '{"en": "Aether Fold Air"}', '{"en": "<p>A book-style foldable that opens into a nearly square canvas. Thin hinges, a bright cover screen, and speakers that finally sound like a phone worth watching on.</p><h3>Highlights</h3><ul><li>7.6-inch foldable main display</li><li>Bright cover screen for one-handed use</li><li>Stereo speakers with spatial audio</li></ul><h3>Details</h3><ul><li><strong>Main display:</strong> 7.6in foldable OLED</li><li><strong>Cover:</strong> 6.2in OLED</li><li><strong>Hinge:</strong> Water-resistant seal</li></ul>"}', 1299.99, NULL, 520.00, 'SKU-0003', NULL, TRUE, 18, 5, TRUE, 0.50, 'kg', 20.00, 15.00, 8.00, 'cm', FALSE, TRUE, '{"en": "Aether Fold Air"}', '{"en": "Aether Fold Air"}', '2026-03-01 10:00:00', '2026-03-01 10:00:00'),
(4, 4, 'standard', 13, 'softcase-silicone-shell', '{"en": "Softcase Silicone Shell"}', '{"en": "<p>A soft-touch silicone case with a microfibre lining that keeps the phone scratch-free. Raised edges protect the camera island and the screen when it lands face-down.</p><h3>Highlights</h3><ul><li>Soft-touch silicone exterior</li><li>Microfibre interior lining</li><li>Raised camera and screen lips</li></ul><h3>Details</h3><ul><li><strong>Compatibility:</strong> Aether Pulse Pro / Lite</li><li><strong>Finish:</strong> Matte silicone</li></ul>"}', 34.99, 44.99, 14.00, 'SKU-0004', NULL, TRUE, 200, 5, TRUE, 0.50, 'kg', 20.00, 15.00, 8.00, 'cm', FALSE, TRUE, '{"en": "Softcase Silicone Shell"}', '{"en": "Softcase Silicone Shell"}', '2026-03-01 10:00:00', '2026-03-01 10:00:00'),
(5, 4, 'standard', 13, 'softcase-clear-armor', '{"en": "Softcase Clear Armor"}', '{"en": "<p>A crystal-clear case that stays clear. Anti-yellowing polymer, military-grade corners, and a slim profile that still feels like the phone.</p><h3>Highlights</h3><ul><li>Anti-yellowing clear polymer</li><li>Reinforced corners</li><li>Wireless charging compatible</li></ul><h3>Details</h3><ul><li><strong>Drop rating:</strong> 3m military standard</li><li><strong>Material:</strong> Clear TPU + hard back</li></ul>"}', 29.99, NULL, 12.00, 'SKU-0005', NULL, TRUE, 160, 5, TRUE, 0.50, 'kg', 20.00, 15.00, 8.00, 'cm', FALSE, TRUE, '{"en": "Softcase Clear Armor"}', '{"en": "Softcase Clear Armor"}', '2026-03-01 10:00:00', '2026-03-01 10:00:00'),
(6, 4, 'standard', 17, 'voltlab-trio-charger', '{"en": "Voltlab Trio Wireless Charger"}', '{"en": "<p>One stand that charges a phone, watch and earbuds together. The phone pad tilts to 60 degrees so notifications stay readable while it tops up.</p><h3>Highlights</h3><ul><li>Three charging pads in one stand</li><li>Phone pad tilts for nightstand use</li><li>Folds flat for travel</li></ul><h3>Details</h3><ul><li><strong>Phone output:</strong> 15W</li><li><strong>Watch:</strong> 5W</li><li><strong>Earbuds:</strong> 5W</li></ul>"}', 89.99, 109.99, 36.00, 'SKU-0006', NULL, TRUE, 85, 5, TRUE, 0.50, 'kg', 20.00, 15.00, 8.00, 'cm', FALSE, TRUE, '{"en": "Voltlab Trio Wireless Charger"}', '{"en": "Voltlab Trio Wireless Charger"}', '2026-03-01 10:00:00', '2026-03-01 10:00:00'),
(7, 4, 'standard', 17, 'voltlab-braided-cable', '{"en": "Voltlab Braided USB-C Cable"}', '{"en": "<p>A 2-metre braided cable that survives the bag. 100W capable, with reinforced strain relief at both ends and a magnetic cable tie.</p><h3>Highlights</h3><ul><li>100W USB-C power delivery</li><li>Braided nylon exterior</li><li>Magnetic cable tie included</li></ul><h3>Details</h3><ul><li><strong>Length:</strong> 2 m</li><li><strong>Rating:</strong> 100W / 20Gbps</li></ul>"}', 24.99, NULL, 10.00, 'SKU-0007', NULL, TRUE, 300, 5, TRUE, 0.50, 'kg', 20.00, 15.00, 8.00, 'cm', FALSE, TRUE, '{"en": "Voltlab Braided USB-C Cable"}', '{"en": "Voltlab Braided USB-C Cable"}', '2026-03-01 10:00:00', '2026-03-01 10:00:00'),
(8, 5, 'standard', 5, 'pixelworks-studio-16', '{"en": "Pixelworks Studio 16"}', '{"en": "<p>A 16-inch creator laptop with a factory-calibrated mini-LED display. Thin bezels, a full-size HDMI port, and fans that stay quiet until you push a heavy export.</p><h3>Highlights</h3><ul><li>16-inch mini-LED, 100% DCI-P3</li><li>Dedicated GPU with 12GB VRAM</li><li>100Wh battery for full workdays</li></ul><h3>Details</h3><ul><li><strong>Display:</strong> 16in mini-LED 120Hz</li><li><strong>Memory:</strong> 32GB unified</li><li><strong>Storage:</strong> 1TB SSD</li></ul>"}', 2199.99, NULL, 880.00, 'SKU-0008', NULL, TRUE, 22, 5, TRUE, 0.50, 'kg', 20.00, 15.00, 8.00, 'cm', FALSE, TRUE, '{"en": "Pixelworks Studio 16"}', '{"en": "Pixelworks Studio 16"}', '2026-03-01 10:00:00', '2026-03-01 10:00:00'),
(9, 5, 'standard', 5, 'pixelworks-air-14', '{"en": "Pixelworks Air 14"}', '{"en": "<p>A featherweight 14-inch ultraportable that still handles multi-track timelines. Fanless under light load, with a keyboard that travels well.</p><h3>Highlights</h3><ul><li>1.2 kg magnesium chassis</li><li>All-day battery life</li><li>Silent under light workloads</li></ul><h3>Details</h3><ul><li><strong>Display:</strong> 14in OLED 90Hz</li><li><strong>Weight:</strong> 1.2 kg</li><li><strong>Ports:</strong> 2x Thunderbolt, HDMI</li></ul>"}', 1299.99, 1399.99, 520.00, 'SKU-0009', NULL, TRUE, 40, 5, TRUE, 0.50, 'kg', 20.00, 15.00, 8.00, 'cm', FALSE, TRUE, '{"en": "Pixelworks Air 14"}', '{"en": "Pixelworks Air 14"}', '2026-03-01 10:00:00', '2026-03-01 10:00:00'),
(10, 5, 'standard', 5, 'pixelworks-edge-15', '{"en": "Pixelworks Edge 15"}', '{"en": "<p>A gaming-capable 15-inch machine dressed like a work laptop. MUX switch graphics, a 165Hz panel, and RGB that you can actually turn off.</p><h3>Highlights</h3><ul><li>165Hz IPS panel with 3ms response</li><li>MUX switch for battery or performance</li><li>Per-key RGB keyboard, off by default</li></ul><h3>Details</h3><ul><li><strong>GPU:</strong> Dedicated 8GB</li><li><strong>RAM:</strong> 16GB DDR5</li><li><strong>Storage:</strong> 1TB NVMe</li></ul>"}', 1799.99, 1999.99, 720.00, 'SKU-0010', NULL, TRUE, 28, 5, TRUE, 0.50, 'kg', 20.00, 15.00, 8.00, 'cm', FALSE, TRUE, '{"en": "Pixelworks Edge 15"}', '{"en": "Pixelworks Edge 15"}', '2026-03-01 10:00:00', '2026-03-01 10:00:00'),
(11, 6, 'standard', 5, 'pixelworks-slate-11', '{"en": "Pixelworks Slate 11"}', '{"en": "<p>An 11-inch tablet that feels like a notebook when you attach the keyboard folio. Pressure-sensitive stylus docks magnetically on the long edge.</p><h3>Highlights</h3><ul><li>11-inch Liquid Retina-class display</li><li>Magnetic stylus with 4096 levels</li><li>Optional keyboard folio</li></ul><h3>Details</h3><ul><li><strong>Display:</strong> 11in 120Hz</li><li><strong>Storage:</strong> 256GB</li><li><strong>Stylus:</strong> Included</li></ul>"}', 649.99, NULL, 260.00, 'SKU-0011', NULL, TRUE, 55, 5, TRUE, 0.50, 'kg', 20.00, 15.00, 8.00, 'cm', FALSE, TRUE, '{"en": "Pixelworks Slate 11"}', '{"en": "Pixelworks Slate 11"}', '2026-03-01 10:00:00', '2026-03-01 10:00:00'),
(12, 6, 'standard', 4, 'aether-canvas-pro', '{"en": "Aether Canvas Pro"}', '{"en": "<p>A 12.9-inch tablet aimed at illustration. Near-zero parallax with the included pen, and a laminated display that feels like paper with a matte screen protector.</p><h3>Highlights</h3><ul><li>12.9-inch laminated mini-LED</li><li>Near-zero pen latency</li><li>Four speakers with landscape balance</li></ul><h3>Details</h3><ul><li><strong>Display:</strong> 12.9in mini-LED</li><li><strong>Pen:</strong> Included, wireless charge</li><li><strong>Storage:</strong> 512GB</li></ul>"}', 899.99, NULL, 360.00, 'SKU-0012', NULL, TRUE, 30, 5, TRUE, 0.50, 'kg', 20.00, 15.00, 8.00, 'cm', FALSE, TRUE, '{"en": "Aether Canvas Pro"}', '{"en": "Aether Canvas Pro"}', '2026-03-01 10:00:00', '2026-03-01 10:00:00'),
(13, 8, 'standard', 4, 'aether-vision-65-oled', '{"en": "Aether Vision 65 OLED"}', '{"en": "<p>A 65-inch OLED with perfect blacks and a processor that cleans up motion without the soap-opera effect. The stand tucks flush or lifts for a soundbar.</p><h3>Highlights</h3><ul><li>65-inch 4K OLED, 120Hz</li><li>Filmmaker mode and Dolby Vision</li><li>Flush or raised stand positions</li></ul><h3>Details</h3><ul><li><strong>Size:</strong> 65in</li><li><strong>HDR:</strong> Dolby Vision, HDR10+</li><li><strong>Ports:</strong> 4x HDMI 2.1</li></ul>"}', 1899.99, 2199.99, 760.00, 'SKU-0013', NULL, TRUE, 14, 5, TRUE, 0.50, 'kg', 20.00, 15.00, 8.00, 'cm', FALSE, TRUE, '{"en": "Aether Vision 65 OLED"}', '{"en": "Aether Vision 65 OLED"}', '2026-03-01 10:00:00', '2026-03-01 10:00:00'),
(14, 8, 'standard', 4, 'aether-vision-55-qled', '{"en": "Aether Vision 55 QLED"}', '{"en": "<p>A bright 55-inch QLED for rooms that fight with daylight. Quantum-dot colour, local dimming, and a clean cable path through the stand.</p><h3>Highlights</h3><ul><li>55-inch 4K QLED</li><li>Full-array local dimming</li><li>Game mode with VRR</li></ul><h3>Details</h3><ul><li><strong>Size:</strong> 55in</li><li><strong>Refresh:</strong> 120Hz</li><li><strong>Smart OS:</strong> Aether OS</li></ul>"}', 899.99, NULL, 360.00, 'SKU-0014', NULL, TRUE, 25, 5, TRUE, 0.50, 'kg', 20.00, 15.00, 8.00, 'cm', FALSE, TRUE, '{"en": "Aether Vision 55 QLED"}', '{"en": "Aether Vision 55 QLED"}', '2026-03-01 10:00:00', '2026-03-01 10:00:00'),
(15, 9, 'standard', 6, 'gameforge-pulse-controller', '{"en": "Gameforge Pulse Controller"}', '{"en": "<p>A wireless controller with adaptive triggers, a textured grip, and a 40-hour battery. Works with console, PC and mobile via Bluetooth.</p><h3>Highlights</h3><ul><li>Adaptive triggers and haptic feedback</li><li>40-hour rechargeable battery</li><li>Bluetooth and 2.4GHz dongle</li></ul><h3>Details</h3><ul><li><strong>Connectivity:</strong> BT 5.2 + 2.4GHz</li><li><strong>Battery:</strong> 40 hours</li><li><strong>Weight:</strong> 280g</li></ul>"}', 69.99, 79.99, 28.00, 'SKU-0015', NULL, TRUE, 120, 5, TRUE, 0.50, 'kg', 20.00, 15.00, 8.00, 'cm', FALSE, TRUE, '{"en": "Gameforge Pulse Controller"}', '{"en": "Gameforge Pulse Controller"}', '2026-03-01 10:00:00', '2026-03-01 10:00:00'),
(16, 9, 'standard', 6, 'gameforge-horizon-vr', '{"en": "Gameforge Horizon VR"}', '{"en": "<p>A standalone VR headset with pancake lenses and a 120Hz display. Controllers charge on the dock included in the box.</p><h3>Highlights</h3><ul><li>Standalone all-in-one headset</li><li>Pancake lenses, 120Hz</li><li>Controllers charge on included dock</li></ul><h3>Details</h3><ul><li><strong>Resolution:</strong> 2x 2160x2160</li><li><strong>Storage:</strong> 256GB</li><li><strong>IPD:</strong> Adjustable</li></ul>"}', 449.99, NULL, 180.00, 'SKU-0016', NULL, TRUE, 35, 5, TRUE, 0.50, 'kg', 20.00, 15.00, 8.00, 'cm', FALSE, TRUE, '{"en": "Gameforge Horizon VR"}', '{"en": "Gameforge Horizon VR"}', '2026-03-01 10:00:00', '2026-03-01 10:00:00'),
(17, 9, 'standard', 6, 'gameforge-apex-headset', '{"en": "Gameforge Apex Headset"}', '{"en": "<p>A lightweight wireless gaming headset with a flip-to-mute boom mic and 50mm drivers that stay clear at high volume.</p><h3>Highlights</h3><ul><li>Flip-to-mute boom microphone</li><li>50mm neodymium drivers</li><li>30-hour battery</li></ul><h3>Details</h3><ul><li><strong>Connectivity:</strong> 2.4GHz + Bluetooth</li><li><strong>Weight:</strong> 280g</li><li><strong>Battery:</strong> 30 hours</li></ul>"}', 129.99, 149.99, 52.00, 'SKU-0017', NULL, TRUE, 70, 5, TRUE, 0.50, 'kg', 20.00, 15.00, 8.00, 'cm', FALSE, TRUE, '{"en": "Gameforge Apex Headset"}', '{"en": "Gameforge Apex Headset"}', '2026-03-01 10:00:00', '2026-03-01 10:00:00'),
(18, 10, 'standard', 18, 'quietroom-solace-anc', '{"en": "Quietroom Solace ANC"}', '{"en": "<p>Over-ear headphones with adaptive noise cancellation and a transparency mode that actually sounds natural. Fold flat into a slim hard case.</p><h3>Highlights</h3><ul><li>Adaptive ANC with transparency mode</li><li>40-hour battery with ANC on</li><li>Multipoint Bluetooth for two devices</li></ul><h3>Details</h3><ul><li><strong>Drivers:</strong> 40mm bio-cellulose</li><li><strong>Battery:</strong> 40 hours ANC on</li><li><strong>Weight:</strong> 250g</li></ul>"}', 279.99, 329.99, 112.00, 'SKU-0018', NULL, TRUE, 60, 5, TRUE, 0.50, 'kg', 20.00, 15.00, 8.00, 'cm', FALSE, TRUE, '{"en": "Quietroom Solace ANC"}', '{"en": "Quietroom Solace ANC"}', '2026-03-01 10:00:00', '2026-03-01 10:00:00'),
(19, 10, 'standard', 18, 'quietroom-pebble-buds', '{"en": "Quietroom Pebble Buds"}', '{"en": "<p>True wireless buds shaped like smooth river stones. Secure fit without silicone tips that hurt after an hour, and ANC that holds on a commute.</p><h3>Highlights</h3><ul><li>Open-fit design with light seal</li><li>Hybrid ANC</li><li>Wireless charging case</li></ul><h3>Details</h3><ul><li><strong>Battery:</strong> 7h buds + 24h case</li><li><strong>IP rating:</strong> IP55</li><li><strong>Codecs:</strong> AAC, LC3</li></ul>"}', 149.99, NULL, 60.00, 'SKU-0019', NULL, TRUE, 110, 5, TRUE, 0.50, 'kg', 20.00, 15.00, 8.00, 'cm', FALSE, TRUE, '{"en": "Quietroom Pebble Buds"}', '{"en": "Quietroom Pebble Buds"}', '2026-03-01 10:00:00', '2026-03-01 10:00:00'),
(20, 10, 'standard', 18, 'quietroom-beam-soundbar', '{"en": "Quietroom Beam Soundbar"}', '{"en": "<p>A low-profile soundbar that fills a living room without a subwoofer box. Wall-mount or shelf, with HDMI eARC and room calibration.</p><h3>Highlights</h3><ul><li>Virtual surround without rear speakers</li><li>HDMI eARC and optical</li><li>Auto room calibration mic</li></ul><h3>Details</h3><ul><li><strong>Channels:</strong> 5.0.2 virtual</li><li><strong>Height:</strong> 58mm</li><li><strong>Width:</strong> 900mm</li></ul>"}', 399.99, NULL, 160.00, 'SKU-0020', NULL, TRUE, 40, 5, TRUE, 0.50, 'kg', 20.00, 15.00, 8.00, 'cm', FALSE, TRUE, '{"en": "Quietroom Beam Soundbar"}', '{"en": "Quietroom Beam Soundbar"}', '2026-03-01 10:00:00', '2026-03-01 10:00:00'),
(21, 34, 'standard', 4, 'aether-hub-mini', '{"en": "Aether Hub Mini"}', '{"en": "<p>A thread and Matter border router that quietly sits on a shelf. One app for lights, locks and sensors — no cloud required for local automations.</p><h3>Highlights</h3><ul><li>Thread and Matter border router</li><li>Local automations without cloud</li><li>Works with major smart home platforms</li></ul><h3>Details</h3><ul><li><strong>Radios:</strong> Thread, Wi-Fi 6, BLE</li><li><strong>Power:</strong> USB-C</li><li><strong>Size:</strong> 80mm cube</li></ul>"}', 99.99, NULL, 40.00, 'SKU-0021', NULL, TRUE, 90, 5, TRUE, 0.50, 'kg', 20.00, 15.00, 8.00, 'cm', FALSE, TRUE, '{"en": "Aether Hub Mini"}', '{"en": "Aether Hub Mini"}', '2026-03-01 10:00:00', '2026-03-01 10:00:00'),
(22, 35, 'standard', 4, 'aether-sense-sensor', '{"en": "Aether Sense Multi-Sensor"}', '{"en": "<p>Temperature, humidity, motion and light in a puck the size of a coaster. Two-year battery, Thread native.</p><h3>Highlights</h3><ul><li>Four sensors in one puck</li><li>2-year coin-cell battery</li><li>Thread native, Matter ready</li></ul><h3>Details</h3><ul><li><strong>Sensors:</strong> Temp, humidity, motion, lux</li><li><strong>Battery:</strong> CR2477, ~2 years</li></ul>"}', 39.99, NULL, 16.00, 'SKU-0022', NULL, TRUE, 200, 5, TRUE, 0.50, 'kg', 20.00, 15.00, 8.00, 'cm', FALSE, TRUE, '{"en": "Aether Sense Multi-Sensor"}', '{"en": "Aether Sense Multi-Sensor"}', '2026-03-01 10:00:00', '2026-03-01 10:00:00'),
(23, 13, 'standard', 1, 'nordform-lounge-chair', '{"en": "Nordform Contour Lounge Chair"}', '{"en": "<p>A moulded plywood shell wrapped in full-grain leather. The aluminium base swivels silently, and the matching ottoman is sold separately.</p><h3>Highlights</h3><ul><li>Moulded plywood shell</li><li>Full-grain aniline leather</li><li>Silent aluminium swivel base</li></ul><h3>Details</h3><ul><li><strong>Materials:</strong> Walnut veneer, black leather</li><li><strong>Width:</strong> 84 cm</li><li><strong>Origin:</strong> Denmark</li></ul>"}', 1299.99, 1499.99, 520.00, 'SKU-0023', NULL, TRUE, 12, 5, TRUE, 0.50, 'kg', 20.00, 15.00, 8.00, 'cm', FALSE, TRUE, '{"en": "Nordform Contour Lounge Chair"}', '{"en": "Nordform Contour Lounge Chair"}', '2026-03-01 10:00:00', '2026-03-01 10:00:00'),
(24, 13, 'standard', 1, 'nordform-dining-chair', '{"en": "Nordform Arc Dining Chair"}', '{"en": "<p>A stackable dining chair with a softly curved back. Solid oak legs and a moulded seat that stays comfortable through long dinners.</p><h3>Highlights</h3><ul><li>Solid oak legs</li><li>Moulded seat with soft curve</li><li>Stackable up to four</li></ul><h3>Details</h3><ul><li><strong>Finish:</strong> Natural oak / sage seat</li><li><strong>Height:</strong> 80 cm</li><li><strong>Seat height:</strong> 46 cm</li></ul>"}', 349.99, NULL, 140.00, 'SKU-0024', NULL, TRUE, 48, 5, TRUE, 0.50, 'kg', 20.00, 15.00, 8.00, 'cm', FALSE, TRUE, '{"en": "Nordform Arc Dining Chair"}', '{"en": "Nordform Arc Dining Chair"}', '2026-03-01 10:00:00', '2026-03-01 10:00:00'),
(25, 13, 'standard', 1, 'nordform-rocking-chair', '{"en": "Nordform Basin Rocking Chair"}', '{"en": "<p>A sculptural rocker carved from a single moulded form. The runners are ash, the body is a warm clay composite that never needs reupholstering.</p><h3>Highlights</h3><ul><li>Single-piece moulded body</li><li>Ash wood runners</li><li>Indoor use, wipe-clean surface</li></ul><h3>Details</h3><ul><li><strong>Material:</strong> Ash + composite</li><li><strong>Width:</strong> 62 cm</li><li><strong>Weight capacity:</strong> 120 kg</li></ul>"}', 589.99, NULL, 236.00, 'SKU-0025', NULL, TRUE, 16, 5, TRUE, 0.50, 'kg', 20.00, 15.00, 8.00, 'cm', FALSE, TRUE, '{"en": "Nordform Basin Rocking Chair"}', '{"en": "Nordform Basin Rocking Chair"}', '2026-03-01 10:00:00', '2026-03-01 10:00:00'),
(26, 13, 'standard', 1, 'nordform-bar-stool', '{"en": "Nordform Counter Stool"}', '{"en": "<p>A counter-height stool with a footrest ring that does not rattle. Soft leather pad, powder-coated steel frame.</p><h3>Highlights</h3><ul><li>65 cm counter height</li><li>Quiet footrest ring</li><li>Removable leather pad</li></ul><h3>Details</h3><ul><li><strong>Height:</strong> 65 cm seat</li><li><strong>Frame:</strong> Powder-coated steel</li><li><strong>Pad:</strong> Aniline leather</li></ul>"}', 279.99, NULL, 112.00, 'SKU-0026', NULL, TRUE, 36, 5, TRUE, 0.50, 'kg', 20.00, 15.00, 8.00, 'cm', FALSE, TRUE, '{"en": "Nordform Counter Stool"}', '{"en": "Nordform Counter Stool"}', '2026-03-01 10:00:00', '2026-03-01 10:00:00'),
(27, 14, 'standard', 1, 'nordform-side-table', '{"en": "Nordform Disc Side Table"}', '{"en": "<p>A round solid-oak side table with a single pedestal. Compact enough for a reading nook, sturdy enough for a heavy lamp.</p><h3>Highlights</h3><ul><li>Solid oak top and base</li><li>50 cm diameter</li><li>Natural oil finish</li></ul><h3>Details</h3><ul><li><strong>Diameter:</strong> 50 cm</li><li><strong>Height:</strong> 48 cm</li><li><strong>Finish:</strong> Natural oil</li></ul>"}', 249.99, NULL, 100.00, 'SKU-0027', NULL, TRUE, 40, 5, TRUE, 0.50, 'kg', 20.00, 15.00, 8.00, 'cm', FALSE, TRUE, '{"en": "Nordform Disc Side Table"}', '{"en": "Nordform Disc Side Table"}', '2026-03-01 10:00:00', '2026-03-01 10:00:00'),
