(56, 23, 'standard', 16, 'threadform-boys-shirt', '{"en": "Threadform Youth White Shirt"}', '{"en": "<p>A crisp white shirt cut for growing kids. Easy-iron cotton, reinforced buttons, and a hem that stays tucked when it needs to.</p><h3>Highlights</h3><ul><li>Easy-iron cotton</li><li>Reinforced buttons</li><li>School and occasion ready</li></ul><h3>Details</h3><ul><li><strong>Material:</strong> 100% cotton</li><li><strong>Ages:</strong> 6–14 / sized by height</li><li><strong>Care:</strong> Machine wash</li></ul>"}', 49.99, NULL, 20.00, 'SKU-0056', NULL, TRUE, 70, 5, TRUE, 0.50, 'kg', 20.00, 15.00, 8.00, 'cm', FALSE, TRUE, '{"en": "Threadform Youth White Shirt"}', '{"en": "Threadform Youth White Shirt"}', '2026-03-01 10:00:00', '2026-03-01 10:00:00'),
(57, 24, 'standard', 15, 'stride-brogue-boots', '{"en": "Stride Brogue Boots"}', '{"en": "<p>Full-grain leather brogue boots with a Goodyear welt. Resoleable, with a cushioned insole that softens after a week of wear.</p><h3>Highlights</h3><ul><li>Full-grain leather upper</li><li>Goodyear welt construction</li><li>Cushioned removable insole</li></ul><h3>Details</h3><ul><li><strong>Sole:</strong> Leather + rubber tip</li><li><strong>Lining:</strong> Leather</li><li><strong>Origin:</strong> Portugal</li></ul>"}', 248.99, NULL, 99.60, 'SKU-0057', NULL, TRUE, 36, 5, TRUE, 0.50, 'kg', 20.00, 15.00, 8.00, 'cm', FALSE, TRUE, '{"en": "Stride Brogue Boots"}', '{"en": "Stride Brogue Boots"}', '2026-03-01 10:00:00', '2026-03-01 10:00:00'),
(58, 24, 'standard', 15, 'stride-suede-boots', '{"en": "Stride Suede Chelsea Boots"}', '{"en": "<p>Chelsea boots in soft brown suede with elastic side panels and a stacked heel. Smart enough for the office, easy enough for weekends.</p><h3>Highlights</h3><ul><li>Soft brown suede</li><li>Elastic side gores</li><li>Stacked leather heel</li></ul><h3>Details</h3><ul><li><strong>Sole:</strong> Leather</li><li><strong>Heel:</strong> 3 cm</li><li><strong>Care:</strong> Suede brush + protector</li></ul>"}', 228.99, 268.99, 91.60, 'SKU-0058', NULL, TRUE, 40, 5, TRUE, 0.50, 'kg', 20.00, 15.00, 8.00, 'cm', FALSE, TRUE, '{"en": "Stride Suede Chelsea Boots"}', '{"en": "Stride Suede Chelsea Boots"}', '2026-03-01 10:00:00', '2026-03-01 10:00:00'),
