(112, 46, 'standard', 2, 'lumenora-task-lamp', '{"en": "Lumenora Task Lamp"}', '{"en": "<p>A articulated task lamp with a warm LED and a weighted base. Dims from full work light to night mode.</p><h3>Highlights</h3><ul><li>Articulated arm</li><li>Warm dimmable LED</li><li>Weighted base</li></ul><h3>Details</h3><ul><li><strong>Height:</strong> Adjustable to 55 cm</li><li><strong>Power:</strong> USB-C</li></ul>"}', 129.99, NULL, 52.00, 'SKU-0112', NULL, TRUE, 40, 5, TRUE, 0.50, 'kg', 20.00, 15.00, 8.00, 'cm', FALSE, TRUE, '{"en": "Lumenora Task Lamp"}', '{"en": "Lumenora Task Lamp"}', '2026-03-01 10:00:00', '2026-03-01 10:00:00'),
(113, 46, 'standard', 2, 'lumenora-clip-lamp', '{"en": "Lumenora Clip Lamp"}', '{"en": "<p>A small clip lamp for shelves and headboards. Soft diffusion, USB powered.</p><h3>Highlights</h3><ul><li>Strong spring clip</li><li>Soft diffused LED</li><li>USB powered</li></ul><h3>Details</h3><ul><li><strong>Cable:</strong> 1.5 m USB-C</li><li><strong>Colour temp:</strong> 3000 K</li></ul>"}', 49.99, NULL, 20.00, 'SKU-0113', NULL, TRUE, 75, 5, TRUE, 0.50, 'kg', 20.00, 15.00, 8.00, 'cm', FALSE, TRUE, '{"en": "Lumenora Clip Lamp"}', '{"en": "Lumenora Clip Lamp"}', '2026-03-01 10:00:00', '2026-03-01 10:00:00'),
(114, 13, 'standard', 1, 'nordform-sofa-chair', '{"en": "Nordform Lounge Armchair"}', '{"en": "<p>A deep armchair with loose cushions and oak legs. Wide enough to curl up with a book.</p><h3>Highlights</h3><ul><li>Loose seat and back cushions</li><li>Solid oak legs</li><li>Performance fabric</li></ul><h3>Details</h3><ul><li><strong>Width:</strong> 95 cm</li><li><strong>Depth:</strong> 90 cm</li><li><strong>Fabric:</strong> Performance weave</li></ul>"}', 899.99, NULL, 360.00, 'SKU-0114', NULL, TRUE, 12, 5, TRUE, 0.50, 'kg', 20.00, 15.00, 8.00, 'cm', FALSE, TRUE, '{"en": "Nordform Lounge Armchair"}', '{"en": "Nordform Lounge Armchair"}', '2026-03-01 10:00:00', '2026-03-01 10:00:00'),
(115, 14, 'standard', 1, 'nordform-coffee-table', '{"en": "Nordform Oval Coffee Table"}', '{"en": "<p>An oval oak coffee table with a soft edge that is kind to shins. Lower shelf for books and remotes.</p><h3>Highlights</h3><ul><li>Solid oak top</li><li>Soft eased edge</li><li>Lower storage shelf</li></ul><h3>Details</h3><ul><li><strong>Length:</strong> 120 cm</li><li><strong>Width:</strong> 60 cm</li><li><strong>Height:</strong> 40 cm</li></ul>"}', 549.99, NULL, 220.00, 'SKU-0115', NULL, TRUE, 15, 5, TRUE, 0.50, 'kg', 20.00, 15.00, 8.00, 'cm', FALSE, TRUE, '{"en": "Nordform Oval Coffee Table"}', '{"en": "Nordform Oval Coffee Table"}', '2026-03-01 10:00:00', '2026-03-01 10:00:00'),
(116, 14, 'standard', 1, 'nordform-bookshelf', '{"en": "Nordform Ladder Bookshelf"}', '{"en": "<p>A leaning ladder bookshelf in oak. Five shelves that get deeper as they go down.</p><h3>Highlights</h3><ul><li>Leaning ladder design</li><li>Five oak shelves</li><li>Wall strap included</li></ul><h3>Details</h3><ul><li><strong>Height:</strong> 180 cm</li><li><strong>Width:</strong> 70 cm</li><li><strong>Material:</strong> Oak</li></ul>"}', 399.99, NULL, 160.00, 'SKU-0116', NULL, TRUE, 20, 5, TRUE, 0.50, 'kg', 20.00, 15.00, 8.00, 'cm', FALSE, TRUE, '{"en": "Nordform Ladder Bookshelf"}', '{"en": "Nordform Ladder Bookshelf"}', '2026-03-01 10:00:00', '2026-03-01 10:00:00'),
(117, 13, 'standard', 1, 'nordform-ottoman', '{"en": "Nordform Soft Ottoman"}', '{"en": "<p>A round upholstered ottoman that works as a footrest or extra seat. Removable cover.</p><h3>Highlights</h3><ul><li>Round soft form</li><li>Removable cover</li><li>Hidden wood feet</li></ul><h3>Details</h3><ul><li><strong>Diameter:</strong> 60 cm</li><li><strong>Height:</strong> 40 cm</li></ul>"}', 249.99, NULL, 100.00, 'SKU-0117', NULL, TRUE, 25, 5, TRUE, 0.50, 'kg', 20.00, 15.00, 8.00, 'cm', FALSE, TRUE, '{"en": "Nordform Soft Ottoman"}', '{"en": "Nordform Soft Ottoman"}', '2026-03-01 10:00:00', '2026-03-01 10:00:00'),
(118, 36, 'standard', 4, 'aether-smart-plug', '{"en": "Aether Smart Plug Duo"}', '{"en": "<p>Two compact smart plugs with energy monitoring. Matter over Wi-Fi, voice assistant ready.</p><h3>Highlights</h3><ul><li>Pack of two</li><li>Energy monitoring</li><li>Matter over Wi-Fi</li></ul><h3>Details</h3><ul><li><strong>Load:</strong> 15 A</li><li><strong>App:</strong> Aether Home</li></ul>"}', 29.99, NULL, 12.00, 'SKU-0118', NULL, TRUE, 150, 5, TRUE, 0.50, 'kg', 20.00, 15.00, 8.00, 'cm', FALSE, TRUE, '{"en": "Aether Smart Plug Duo"}', '{"en": "Aether Smart Plug Duo"}', '2026-03-01 10:00:00', '2026-03-01 10:00:00'),
(119, 36, 'standard', 4, 'aether-dimmer-switch', '{"en": "Aether Smart Dimmer Switch"}', '{"en": "<p>An in-wall smart dimmer with a soft click paddle. Works with LED loads and Matter hubs.</p><h3>Highlights</h3><ul><li>In-wall paddle dimmer</li><li>LED compatible</li><li>Matter ready</li></ul><h3>Details</h3><ul><li><strong>Load:</strong> 150 W LED</li><li><strong>Colour:</strong> White</li></ul>"}', 44.99, NULL, 18.00, 'SKU-0119', NULL, TRUE, 80, 5, TRUE, 0.50, 'kg', 20.00, 15.00, 8.00, 'cm', FALSE, TRUE, '{"en": "Aether Smart Dimmer Switch"}', '{"en": "Aether Smart Dimmer Switch"}', '2026-03-01 10:00:00', '2026-03-01 10:00:00'),
(120, 35, 'standard', 4, 'aether-door-sensor', '{"en": "Aether Door & Window Sensor"}', '{"en": "<p>A slim magnetic contact for doors and windows. Two-year battery, Thread native.</p><h3>Highlights</h3><ul><li>Slim magnetic contact</li><li>2-year battery</li><li>Thread native</li></ul><h3>Details</h3><ul><li><strong>Battery:</strong> CR2032</li><li><strong>Range:</strong> Typical home</li></ul>"}', 24.99, NULL, 10.00, 'SKU-0120', NULL, TRUE, 120, 5, TRUE, 0.50, 'kg', 20.00, 15.00, 8.00, 'cm', FALSE, TRUE, '{"en": "Aether Door & Window Sensor"}', '{"en": "Aether Door & Window Sensor"}', '2026-03-01 10:00:00', '2026-03-01 10:00:00'),
(121, 48, 'standard', 9, 'fieldcraft-yoga-mat', '{"en": "Fieldcraft Travel Yoga Mat"}', '{"en": "<p>A thin travel yoga mat that rolls small. Grip when wet, no rubber smell.</p><h3>Highlights</h3><ul><li>Thin travel thickness</li><li>Wet-grip surface</li><li>Carrying strap</li></ul><h3>Details</h3><ul><li><strong>Size:</strong> 183 x 61 cm</li><li><strong>Thickness:</strong> 3 mm</li></ul>"}', 48.99, NULL, 19.60, 'SKU-0121', NULL, TRUE, 70, 5, TRUE, 0.50, 'kg', 20.00, 15.00, 8.00, 'cm', FALSE, TRUE, '{"en": "Fieldcraft Travel Yoga Mat"}', '{"en": "Fieldcraft Travel Yoga Mat"}', '2026-03-01 10:00:00', '2026-03-01 10:00:00'),
(122, 48, 'standard', 9, 'fieldcraft-yoga-block', '{"en": "Fieldcraft Cork Yoga Block"}', '{"en": "<p>A dense cork block that does not compress under load. Soft edges for knees and hands.</p><h3>Highlights</h3><ul><li>Dense natural cork</li><li>Soft eased edges</li><li>Stable under load</li></ul><h3>Details</h3><ul><li><strong>Size:</strong> 23 x 15 x 7.5 cm</li><li><strong>Material:</strong> Cork</li></ul>"}', 18.99, NULL, 7.60, 'SKU-0122', NULL, TRUE, 100, 5, TRUE, 0.50, 'kg', 20.00, 15.00, 8.00, 'cm', FALSE, TRUE, '{"en": "Fieldcraft Cork Yoga Block"}', '{"en": "Fieldcraft Cork Yoga Block"}', '2026-03-01 10:00:00', '2026-03-01 10:00:00'),
(123, 49, 'standard', 9, 'fieldcraft-foam-roller', '{"en": "Fieldcraft Foam Roller"}', '{"en": "<p>A firm foam roller for recovery days. Textured surface without being aggressive.</p><h3>Highlights</h3><ul><li>Firm density foam</li><li>Textured surface</li><li>Hollow core for storage</li></ul><h3>Details</h3><ul><li><strong>Length:</strong> 45 cm</li><li><strong>Diameter:</strong> 14 cm</li></ul>"}', 32.99, NULL, 13.20, 'SKU-0123', NULL, TRUE, 60, 5, TRUE, 0.50, 'kg', 20.00, 15.00, 8.00, 'cm', FALSE, TRUE, '{"en": "Fieldcraft Foam Roller"}', '{"en": "Fieldcraft Foam Roller"}', '2026-03-01 10:00:00', '2026-03-01 10:00:00'),
(124, 49, 'standard', 9, 'fieldcraft-resistance-bands', '{"en": "Fieldcraft Resistance Band Set"}', '{"en": "<p>Three loop bands in light, medium and heavy. Carry pouch included.</p><h3>Highlights</h3><ul><li>Three resistance levels</li><li>Latex-free loops</li><li>Carry pouch included</li></ul><h3>Details</h3><ul><li><strong>Levels:</strong> Light / Medium / Heavy</li><li><strong>Material:</strong> Fabric-covered</li></ul>"}', 26.99, NULL, 10.80, 'SKU-0124', NULL, TRUE, 90, 5, TRUE, 0.50, 'kg', 20.00, 15.00, 8.00, 'cm', FALSE, TRUE, '{"en": "Fieldcraft Resistance Band Set"}', '{"en": "Fieldcraft Resistance Band Set"}', '2026-03-01 10:00:00', '2026-03-01 10:00:00'),
(125, 49, 'standard', 9, 'fieldcraft-jump-rope', '{"en": "Fieldcraft Speed Jump Rope"}', '{"en": "<p>A light speed rope with adjustable cable and soft grips. Ball bearings in the handles.</p><h3>Highlights</h3><ul><li>Adjustable cable length</li><li>Ball-bearing handles</li><li>Soft grips</li></ul><h3>Details</h3><ul><li><strong>Cable:</strong> Steel with PVC coat</li><li><strong>Handles:</strong> Soft-touch</li></ul>"}', 19.99, NULL, 8.00, 'SKU-0125', NULL, TRUE, 110, 5, TRUE, 0.50, 'kg', 20.00, 15.00, 8.00, 'cm', FALSE, TRUE, '{"en": "Fieldcraft Speed Jump Rope"}', '{"en": "Fieldcraft Speed Jump Rope"}', '2026-03-01 10:00:00', '2026-03-01 10:00:00');
