(1, 'hero_slider', '{"en": "Welcome"}', '{"slides": [{"image": 234, "headline": {"en": "Charge everything, calmly"}, "subtext": {"en": "Stands, cables and cases designed for a desk that stays tidy."}, "button_text": {"en": "Shop accessories"}, "button_url": "/categories/phone-accessories", "text_color": "dark", "text_align": "left"}, {"image": 235, "headline": {"en": "Furniture with quiet confidence"}, "subtext": {"en": "Nordform seating and tables for rooms you actually live in."}, "button_text": {"en": "Shop furniture"}, "button_url": "/categories/furniture", "text_color": "dark", "text_align": "left"}, {"image": 236, "headline": {"en": "New season layers"}, "subtext": {"en": "Knits, boots and finishing pieces from Aurelia and Stride."}, "button_text": {"en": "Shop fashion"}, "button_url": "/categories/fashion", "text_color": "dark", "text_align": "left"}], "side_tiles": [{"image": 237, "title": {"en": "Quietroom audio week"}, "subtitle": {"en": "Save on headphones and soundbars"}, "url": "/categories/audio", "text_color": "light", "text_align": "top-center"}, {"image": 238, "title": {"en": "The kitchen edit"}, "subtitle": {"en": "Tools you will reach for every morning"}, "url": "/categories/kitchen-dining", "text_color": "dark", "text_align": "top-left"}], "autoplay": true, "autoplay_speed": 6000, "transition": "fade", "show_dots": true}', 1, TRUE, '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
