(11, 'testimonials', '{"en": "What Our Customers Say"}', '{"testimonials": [{"quote": {"en": "The quality of everything I have ordered has been outstanding. FlexStore is my go-to for design and lifestyle pieces."}, "author_name": {"en": "Sarah Johnson"}, "rating": 5}, {"quote": {"en": "Fast shipping, great prices, and the support team was incredibly helpful with my questions."}, "author_name": {"en": "Michael Chen"}, "rating": 5}, {"quote": {"en": "From lighting to decor, everything feels premium. The packaging is impressive too."}, "author_name": {"en": "Emily Rodriguez"}, "rating": 5}, {"quote": {"en": "Ordered a wine cooler on a Tuesday and it was installed by Thursday."}, "author_name": {"en": "Priya Raman"}, "rating": 5}, {"quote": {"en": "I returned a jacket that did not fit and the refund landed before the parcel was scanned in."}, "author_name": {"en": "Tom Beckett"}, "rating": 5}, {"quote": {"en": "The product photos are honest. Three orders in and nothing has arrived looking different."}, "author_name": {"en": "Hannah Okafor"}, "rating": 4}]}', 11, TRUE, '2026-01-01 00:00:00', '2026-01-01 00:00:00');
