UPDATE settings SET value = '<p class="lead">We want you to be completely satisfied with your purchase. If you''re not happy with your order, we''re here to help.</p>
<h2>Returns</h2>
<p>You have <strong>30 days</strong> from the date of delivery to return most items for a full refund. Items must be:</p>
<ul><li>Unused and in the same condition that you received them</li><li>In the original packaging</li><li>Accompanied by the receipt or proof of purchase</li></ul>
<h2>Non-Returnable Items</h2>
<p>Certain items cannot be returned, including:</p>
<ul><li>Gift cards</li><li>Downloadable products</li><li>Perishable goods</li><li>Personal care items</li><li>Items marked as final sale</li></ul>
<h2>Refunds</h2>
<p>Once we receive your returned item, we will inspect it and notify you of the approval or rejection of your refund. If approved, your refund will be processed within <strong>5-7 business days</strong> to your original payment method.</p>
<h2>Exchanges</h2>
<p>If you need to exchange an item for the same product in a different size or color, please contact us at <a href="mailto:hello@flexstore.app">hello@flexstore.app</a>.</p>
<h2>Shipping Costs</h2>
<p>Return shipping costs are the responsibility of the customer unless the return is due to our error. In such cases, we will provide a prepaid shipping label.</p>' WHERE "key" = 'refund_policy';
UPDATE settings SET value = '<p class="lead">This Privacy Policy describes how we collect, use, and share information about you when you use our website and services.</p>
<h2>Information We Collect</h2>
<h3>Information You Provide</h3>
<p>We collect information you provide directly to us, such as when you create an account, make a purchase, subscribe to our newsletter, or contact customer support.</p>
<h2>How We Use Your Information</h2>
<p>We use the information we collect to process and fulfill your orders, send you order confirmations and updates, respond to your questions, and improve our website and services.</p>
<h2>Information Sharing</h2>
<p>We do not sell your personal information. We may share your information with service providers who help us operate our business.</p>
<h2>Your Rights</h2>
<p>You have the right to access and update your personal information, request deletion of your data, and opt out of marketing communications.</p>
<h2>Contact Us</h2>
<p>If you have questions about this Privacy Policy, please contact us at <a href="mailto:hello@flexstore.app">hello@flexstore.app</a>.</p>' WHERE "key" = 'privacy_policy';
UPDATE settings SET value = '<p class="lead">Please read these Terms of Service carefully before using our website.</p>
<h2>1. Acceptance of Terms</h2>
<p>By accessing and using this website, you accept and agree to be bound by these Terms of Service and our Privacy Policy.</p>
<h2>2. Use of Our Service</h2>
<p>You agree to use our service only for lawful purposes and in accordance with these terms.</p>
<h2>3. Products and Pricing</h2>
<p>We strive to display accurate product information and pricing. We reserve the right to correct any errors in pricing or product descriptions.</p>
<h2>4. Payment Terms</h2>
<p>By placing an order, you agree to pay the full amount, including applicable taxes and shipping fees.</p>
<h2>5. Shipping and Delivery</h2>
<p>Shipping times are estimates and not guaranteed. We are not responsible for delays caused by carriers or circumstances beyond our control.</p>
<h2>6. Contact Information</h2>
<p>If you have any questions about these Terms of Service, please contact us at <a href="mailto:hello@flexstore.app">hello@flexstore.app</a>.</p>' WHERE "key" = 'terms_of_service';

